    remarks = #{remarks}
WHERE id = #{id}

UPDATE order_info
SET status = #{toStatus}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{fromStatus}

UPDATE order_info
SET status = '0'
WHERE user_id = #{userId}
  AND order_count = #{orderCount}
  AND type = '1'
  AND status IN ('1', '2')

